namespace Inventory;

/// <summary>
/// Coordinates stock adjustments, reorder decisions, zone allocation and
/// supplier orders.
/// </summary>
public sealed class StockController
{
    private readonly StockAdjustments _adjustments;
    private readonly ReorderPolicy _reorders;
    private readonly ZoneAllocator _zones;
    private readonly SupplierOrders _orders;
    private readonly StockAnalysis _analysis;

    public StockController(ISupplier supplier)
    {
        _adjustments = new StockAdjustments();
        _reorders = new ReorderPolicy();
        _zones = new ZoneAllocator();
        _orders = new SupplierOrders(supplier, _reorders);
        _analysis = new StockAnalysis(_reorders, _zones);
    }

    public int AdjustStock(StockItem item, int delta) =>
        _adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) =>
        _adjustments.Available(item);

    public int MovementCount => _adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) =>
        _reorders.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) =>
        _reorders.ReorderQuantity(item);

    public int ResolveThreshold(string sku) =>
        _reorders.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _zones.Allocate(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) =>
        _zones.GetSpareCapacity(warehouse);

    public bool PlaceReorder(StockItem item) =>
        _orders.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _orders.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) =>
        _analysis.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _analysis.Audit(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _analysis.ForecastDepletion(item, dailyDemand);

    private sealed class StockAdjustments
    {
        private readonly List<string> _movements = new();

        public int MovementCount => _movements.Count;

        public int AdjustStock(StockItem item, int delta)
        {
            if (delta == 0)
                return item.OnHand;
            if (delta < 0 && item.OnHand + delta < 0)
                return item.OnHand;

            item.OnHand += delta;
            if (delta > 0)
                _movements.Add($"IN {item.Sku} {delta}");
            else
                _movements.Add($"OUT {item.Sku} {-delta}");

            if (item.OnHand < item.Reserved)
                _movements.Add($"WARN {item.Sku} oversold");

            return item.OnHand;
        }

        public int Available(StockItem item)
        {
            int free = item.OnHand - item.Reserved;
            if (free < 0)
                return 0;
            return free;
        }
    }

    private sealed class ReorderPolicy
    {
        private readonly Dictionary<string, int> _thresholds = new(StringComparer.Ordinal);
        private readonly int _defaultReorder = 20;

        public bool NeedsReorder(StockItem item)
        {
            if (item.Sku.Length == 0)
                return false;

            int available = item.OnHand - item.Reserved;
            int threshold = ResolveThreshold(item.Sku);
            if (item.ReorderPoint > 0)
                return available <= item.ReorderPoint;
            return available <= threshold;
        }

        public int ReorderQuantity(StockItem item)
        {
            if (!NeedsReorder(item))
                return 0;

            int available = item.OnHand - item.Reserved;
            int target = item.ReorderPoint > 0
                ? item.ReorderPoint * 2
                : _defaultReorder * 2;
            int quantity = target - available;

            if (quantity < 0)
                quantity = 0;
            else if (quantity < 5)
                quantity = 5;

            return quantity;
        }

        public int ResolveThreshold(string sku)
        {
            if (string.IsNullOrEmpty(sku))
                return _defaultReorder;
            if (_thresholds.TryGetValue(sku, out var threshold))
                return threshold;
            return _defaultReorder;
        }
    }

    private sealed class ZoneAllocator
    {
        private readonly Dictionary<string, int> _usage = new(StringComparer.Ordinal);

        public string Allocate(StockItem item, Warehouse warehouse)
        {
            if (warehouse.Zones.Count == 0)
                return "no zones";

            int need = item.OnHand - item.Reserved;
            if (need <= 0)
                return "nothing to place";

            foreach (var zone in warehouse.Zones)
            {
                int used = GetUsage(zone.Name);
                int spare = zone.Capacity - used;
                if (spare <= 0)
                    continue;

                int place = need > spare ? spare : need;
                _usage[zone.Name] = used + place;
                need -= place;
                if (need <= 0)
                    return $"placed in {zone.Name}";
            }

            return "overflow";
        }

        public int GetSpareCapacity(Warehouse warehouse)
        {
            int spare = 0;
            foreach (var zone in warehouse.Zones)
            {
                int used = GetUsage(zone.Name);
                if (zone.Capacity > used)
                    spare += zone.Capacity - used;
            }
            return spare;
        }

        public int GetUsage(string zoneName) =>
            _usage.TryGetValue(zoneName, out var used) ? used : 0;
    }

    private sealed class SupplierOrders
    {
        private readonly ISupplier _supplier;
        private readonly ReorderPolicy _reorders;
        private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

        public SupplierOrders(ISupplier supplier, ReorderPolicy reorders)
        {
            _supplier = supplier;
            _reorders = reorders;
        }

        public bool PlaceReorder(StockItem item)
        {
            int quantity = _reorders.ReorderQuantity(item);
            if (quantity <= 0)
                return false;
            if (_pending.TryGetValue(item.Sku, out var existing) && existing >= quantity)
                return false;

            bool accepted = _supplier.PlaceOrder(item.Sku, quantity);
            if (accepted)
                _pending[item.Sku] = quantity;
            return accepted;
        }

        public bool ConfirmDelivery(StockItem item, int delivered)
        {
            if (delivered <= 0)
                return false;
            if (!_pending.TryGetValue(item.Sku, out var quantity))
                return false;

            item.OnHand += delivered;
            if (delivered >= quantity)
                _pending.Remove(item.Sku);
            else
                _pending[item.Sku] = quantity - delivered;
            return true;
        }
    }

    private sealed class StockAnalysis
    {
        private readonly ReorderPolicy _reorders;
        private readonly ZoneAllocator _zones;

        public StockAnalysis(ReorderPolicy reorders, ZoneAllocator zones)
        {
            _reorders = reorders;
            _zones = zones;
        }

        public string Classify(StockItem item)
        {
            int available = item.OnHand - item.Reserved;
            if (available < 0)
                return "oversold";
            if (available == 0)
                return "out";
            if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
                return "low";
            if (available > item.ReorderPoint * 5)
                return "excess";
            return "ok";
        }

        public IReadOnlyList<string> Audit(StockItem item, Warehouse warehouse)
        {
            var findings = new List<string>();
            if (item.OnHand < 0)
                findings.Add($"{item.Sku}:negative-onhand");
            if (item.Reserved < 0)
                findings.Add($"{item.Sku}:negative-reserve");
            if (item.OnHand < item.Reserved)
                findings.Add($"{item.Sku}:oversold");

            foreach (var zone in warehouse.Zones)
            {
                int used = _zones.GetUsage(zone.Name);
                if (used > zone.Capacity)
                    findings.Add($"{zone.Name}:over-capacity");
                else if (used < 0)
                    findings.Add($"{zone.Name}:negative-usage");
            }

            if (findings.Count == 0)
                findings.Add("clean");
            return findings;
        }

        public int ForecastDepletion(StockItem item, int dailyDemand)
        {
            if (dailyDemand <= 0)
                return -1;

            int available = item.OnHand - item.Reserved;
            if (available <= 0)
                return 0;

            int days = available / dailyDemand;
            if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
                return 0;
            if (days > 365)
                return 365;

            int threshold = _reorders.ResolveThreshold(item.Sku);
            if (threshold > 0 && available <= threshold)
                return 1;
            if (days < 7)
                return days;
            return days;
        }
    }
}
